from typing import List

def possible_values(n: int, k: int, coins: List[int]) -> List[int]:
    dp = [False] * (k + 1)
    dp[0] = True

    # Find all subsets that sum up to k
    for coin in coins:
        if coin > k:
            continue
        for j in range(k, coin - 1, -1):
            if dp[j - coin]:
                dp[j] = True

    result = []
    for i in range(k + 1):
        if dp[i]:
            for j in range(i + 1):
                if not dp[j]:
                    result.append(j)
                    break
            else:
                result.append(i)

    return len(result), sorted(set(result))

