        for j in range(k, coin - 1, -1):
            possible[j] |= possible[j - coin]

    values = []
    for i in range(k + 1):
        if possible[i]:
            for j in range(i // 2 + 1):
                if possible[j] and possible[i - j]:
                    values.append(j)
