from collections import deque

def find_possible_values(n, k, coins):
    possible_values = set()
    queue = deque([0])

    while queue:
        current_sum = queue.popleft()

        if current_sum == k:
            possible_values.add(current_sum)

        if current_sum + coins[0] <= k:
            new_sum = current_sum + coins[0]
            if new_sum not in possible_values:
                possible_values.add(new_sum)
                queue.append(new_sum)

        if len(coins) > 1:
            queue.append(current_sum)

    return sorted(possible_values)

