    dp[0] = True

    for coin in coins:
        for j in range(k, coin - 1, -1):
            dp[j] |= dp[j - coin]

    result = []
    for x in range(k + 1):
        if dp[x]:
            subset_dp = [False] * (x + 1)
            subset_dp[0] = True
            for j in range(1, x + 1):
                if dp[j]:
                    subset_dp[j] = True
                elif j >= coin:
                    subset_dp[j] |= subset_dp[j - coin]
            if any(subset_dp[i] for i in range(x)):
                result.append(x)

    return len(result), sorted(result)

