    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    coins = list(map(int, data[2:]))

    # Initialize dp array where dp[i] is True if we can form sum i using the given coins
    max_val = k + 1
    dp = [False] * max_val
    dp[0] = True

    # Fill the dp array
    for coin in coins:
        for j in range(max_val - 1, coin - 1, -1):
            dp[j] |= dp[j - coin]

    # Collect all possible sums that can be formed using any subset of coins including those used to form k
    possible_sums = set()
    for i in range(1, k + 1):
        if dp[i]:
            for j in range(i, max_val):
                if dp[j]:
                    possible_sums.add(j)

    # Check which of these sums can also be formed without using the coins that sum up to k
    final_sums = set()
    for s in possible_sums:
        remaining = s - k
        if remaining == 0 or not dp[remaining]:
            final_sums.add(s)

    # Output the results
    print(len(final_sums))
    print(" ".join(map(str, sorted(final_sums))))

