from typing import List

def find_possible_values(n: int, k: int, coins: List[int]) -> List[int]:
    dp = [False] * (k + 1)
    dp[0] = True

    for coin in coins:
        for j in range(k, coin - 1, -1):
            if dp[j - coin]:
                dp[j] = True

    possible_values = []
    for i in range(k + 1):
        if dp[i]:
            subset_dp = [False] * (i + 1)
            subset_dp[0] = True
            for sub_coin in coins:
                for j in range(i, sub_coin - 1, -1):
                    if subset_dp[j - sub_coin]:
                        subset_dp[j] = True

            for x in range(i + 1):
                if subset_dp[x]:
                    possible_values.append(x)

    return sorted(list(set(possible_values)))

